  "sql": "SELECT\n  regions.name AS \"customers.regions.name\",\n  COUNT(*) AS \"customers.count_all\"\nFROM customers AS customers\nLEFT JOIN regions AS regions\n  ON customers.region_id = regions.id\nWHERE\n  NOT customers.tags IS NULL\n  AND NOT CASE\n    WHEN customers.tags IS NULL OR 'vip' IS NULL\n    THEN NULL\n    ELSE LIST_CONTAINS([__slayer_e FOR __slayer_e IN customers.tags IF __slayer_e IS NOT NULL], 'vip')\n  END\nGROUP BY\n  regions.name\nORDER BY\n  \"customers.regions.name\" ASC\nLIMIT 101"
